        "head_sha": lease["head_sha"],
        "state": "claimed",
        "lease_acquired_at": acquired,
        "last_seen_at": lease["updated_at"],
        "released_at": None,
    }
    cp = run([
        sys.executable, str(consumer), "execution-context", "--repo-root", str(root),
        "--graph", str(graph), "--graph-node-id", lease["graph_node_id"],
